INSERT INTO SCM_MGR.GT_DM35_SCP_ITEM_INFO (DIVISION_ID, ITEM_ID, CELL_NICKNAME, BASIC_NICKNAME_CELL40, NICKNAME_40 , GROUP_CODE1, GROUP_CODE4, GROUP_CODE5, GROUP_CODE6, GROUP_CODE7, CELL_TYPE_GROUP_NAME) SELECT * FROM ( SELECT SCP_P.DIVISION_ID , SCP_P.ITEM_ID , SCP_P.CELL_NICKNAME , SCP_P.BASIC_NICKNAME_CELL40 , SCP_P.NICKNAME_40 , SCP_P.GROUP_CODE1 , SCP_P.GROUP_CODE4 , SCP_P.GROUP_CODE5 , SCP_P.GROUP_CODE6 , SCP_P.GROUP_CODE7 , CASE WHEN SCP_P.LEVEL_EXCEPT = 'EC' THEN 'POUCH' WHEN SCP_P.LEVEL_EXCEPT = 'AM' THEN 'CYLINDRICAL' WHEN SUBSTR(SCP_P.ITEM_ID, 3, 1) = 'M' AND SCP_P.OPERATION_ID = 'P9500' THEN 'POUCH' ELSE SCP_G.CELL_TYPE_GROUP_NAME END AS CELL_TYPE_GROUP_NAME FROM ( SELECT DIVISION_ID , FLOW_ID AS OPERATION_ID , ITEM_ID , SUBSTR(A.ITEM_ID, 3, 1) AS CELL_TYPE_CODE , SUBSTR(A.ITEM_ID, 1, 2) AS LEVEL_EXCEPT , CASE WHEN SUBSTR(A.DIVISION_ID, 1, 2) = '81' THEN GROUP_CODE1 WHEN A.DIVISION_ID = '82' THEN LEVEL2_CODE ELSE '' END AS CELL_NICKNAME , CASE WHEN SUBSTR(A.ITEM_ID, 1, 2) = 'EC' THEN 'ESS' WHEN SUBSTR(A.ITEM_ID, 1, 2) = 'AM' THEN 'M50L' ELSE CASE WHEN A.OPERATION_GROUP = 'P' THEN (SELECT NICK_NAME FROM SCM_MGR.SCP_MST_FINAL_ITEM B WHERE B.DIVISION_ID = A.DIVISION_ID AND B.ITEM_ID = (SELECT DOE FROM SCM_MGR.GT_DM35_ITEM_SINGLE_ORI B WHERE B.DIVISION_ID = A.DIVISION_ID AND B.ITEM_ID = A.ATTRIBUTE1 AND B.DOE IS NOT NULL AND ROWNUM = 1)) ELSE (SELECT NICK_NAME FROM SCM_MGR.SCP_MST_FINAL_ITEM B WHERE B.DIVISION_ID = A.DIVISION_ID AND B.ITEM_ID = (SELECT DOE FROM SCM_MGR.GT_DM35_ITEM_SINGLE_ORI B WHERE B.DIVISION_ID = A.DIVISION_ID AND B.ITEM_ID = A.ITEM_ID AND B.DOE IS NOT NULL AND ROWNUM = 1)) END END AS BASIC_NICKNAME_CELL40 , A.NICK_NAME AS NICKNAME_40 , A.GROUP_CODE4, A.GROUP_CODE5, A.GROUP_CODE6, A.GROUP_CODE7, A.GROUP_CODE1 , CASE WHEN A.FLOW_ID IN ('A3000', 'A9000') THEN 'C' ELSE 'E' END AS FLOW_TYPE FROM SCM_MGR.SCP_MST_FINAL_ITEM A WHERE 1=1 AND (SUBSTR(A.ATTRIBUTE8, 1, 2) <> 'CA' OR NVL(A.ATTRIBUTE8,'@#@#@#') = '@#@#@#' OR A.ATTRIBUTE8 IS NULL) AND A.DIVISION_ID = :B2 AND ((:B1 IS NULL OR NVL(:B1 ,'@#@#@#') = '@#@#@#') OR A.ITEM_ID IN (SELECT TRIM(REGEXP_SUBSTR(:B1 , '[^,]+', 1, LEVEL)) FROM DUAL CONNECT BY REGEXP_SUBSTR(:B1 , '[^,]+', 1, LEVEL) IS NOT NULL)) ) SCP_P LEFT OUTER JOIN ( SELECT A.SEGMENT1 AS CELL_TYPE_CODE , SUBSTR(A.SEGMENT2, 1, 1) AS FLOW_TYPE , A.SEGMENT3 AS CELL_TYPE_GROUP_CODE , G.SEGMENT2 AS CELL_TYPE_GROUP_NAME , A.DISPLAY_SEQ FROM ( SELECT B.SEGMENT1, B.SEGMENT2, B.SEGMENT3, B.DISPLAY_SEQ FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER A JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL B ON A.LOOKUP_TYPE = B.LOOKUP_TYPE AND B.VALID_YN = 'Y' WHERE A.LOOKUP_TYPE = 'CELL_TYPE_ITEM_CODE' AND A.VALID_YN = 'Y' ) A JOIN ( SELECT B.SEGMENT1, B.SEGMENT2 FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER A2 JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL B ON A2.LOOKUP_TYPE = B.LOOKUP_TYPE AND B.VALID_YN = 'Y' WHERE A2.LOOKUP_TYPE = 'CELL_TYPE_ITEM_GROUP' AND A2.VALID_YN = 'Y' ) G ON A.SEGMENT3 = G.SEGMENT1 ) SCP_G ON SCP_G.FLOW_TYPE = SCP_P.FLOW_TYPE AND SCP_G.CELL_TYPE_CODE = SCP_P.CELL_TYPE_CODE ) T